{"implementation": "def solve(case):
    import sys
    # Validate input
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'lengths' not in case or 'scores' not in case or 'budget' not in case:
        raise ValueError('Missing required fields: lengths, scores, budget')
    lengths = case['lengths']
    scores = case['scores']
    budget = case['budget']
    if not isinstance(lengths, list) or not isinstance(scores, list):
        raise ValueError('lengths and scores must be lists')
    if len(lengths) != len(scores):
        raise ValueError('lengths and scores must have same length')
    n = len(lengths)
    if n == 0:
        return {'selected_indices': [], 'tokens_used': 0, 'total_score': 0.0}
    if not all(isinstance(l, int) and l >= 0 for l in lengths):
        raise ValueError('lengths must be non-negative integers')
    if not all(isinstance(s, (int, float)) for s in scores):
        raise ValueError('scores must be numbers')
    if not isinstance(budget, int) or budget < 0:
        raise ValueError('budget must be a non-negative integer')

    # DP array: for each token count, store (score, tokens, indices_tuple) or None
    dp = [None] * (budget + 1)
    dp[0] = (0.0, 0, ())

    for i in range(n):
        l = lengths[i]
        s = scores[i]
        for j in range(budget, l - 1, -1):
            prev = dp[j - l]
            if prev is not None:
                cand = (prev[0] + s, prev[1] + l, prev[2] + (i,))
                cur = dp[j]
                if cur is None:
                    dp[j] = cand
                else:
                    # Compare by (-score, tokens, indices) lexicographically
                    cand_tuple = (-cand[0], cand[1], cand[2])
                    cur_tuple = (-cur[0], cur[1], cur[2])
                    if cand_tuple < cur_tuple:
                        dp[j] = cand

    # Find best among all feasible token counts
    best = None
    best_key = None
    for j in range(budget + 1):
        cur = dp[j]
        if cur is None:
            continue
        key = (-cur[0], cur[1], cur[2])
        if best is None or key < best_key:
            best = cur
            best_key = key

    if best is None:
        # Only empty selection is feasible (e.g., budget 0)
        best = (0.0, 0, ())

    selected_indices = list(best[2])
    tokens_used = best[1]
    total_score = best[0]
    return {'selected_indices': selected_indices, 'tokens_used': tokens_used, 'total_score': total_score}"}
